/**
 * Design token registry: the single authored source for every visual and motion decision.
 *
 * Everything else derives from this file:
 * - `src/design-system/generated/_tokens.scss` (Sass variables, media queries) and
 *   `src/design-system/generated/_themes.scss` (theme custom properties) are generated by
 *   `bun run tokens` (also run by the Vite dev server and build) and checked by tests.
 * - `src/design-system/index.ts` adapts these values for TS/TSX (motion seconds, media query
 *   strings, palettes).
 *
 * Rules (see docs/design-tokens.md):
 * - Keep this file pure data with no imports. Scales are separate per property semantics: the
 *   same 12 means different things in `fontSize` and `space`.
 * - Scale keys encode the step value (`space['12']` is 12px). Default units: px for lengths, ms
 *   for time, unitless for weights, opacity and z-index. A key with a unit suffix (`'0-25em'`,
 *   `'20px'` in lineHeight) carries that explicit unit. Roles shared across components get
 *   named entries (`size['touch-target']`, `duration['modal-exit']`) that callers prefer.
 * - Theme colours live in `themes`; static palettes (provider badges, charts, decorative plan
 *   badges) live in `palette`. Never hard-code a colour, length, layer or timing elsewhere.
 */

/** `rgba()` string for a hex colour and alpha, so composite tokens can tint palette colours. */
const rgba = (hex: string, alpha: number) => {
  const value = hex.replace('#', '');
  const full = value.length === 3 ? value.replace(/./g, (c) => c + c) : value;
  const [r, g, b] = [0, 2, 4].map((i) => Number.parseInt(full.slice(i, i + 2), 16));
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
};

